CREATE Proc [dbo].[UspInsertItemUPL] @SBId as int, @Item as nvarchar(50), @GRId as int, @ItemCode as nvarchar(50), @Type as int, @PkUnit as int, @PkFactor decimal(18,2), @PurUnit int, @PurFactor decimal(18,2), @IssUnit int, @IssFactor as decimal(18,2), @RecpUnit int, @RecpFactor as decimal(18,2), @Yield as decimal(18,2), @XML xml  as BEGIN TRY    BEGIN TRANSACTION  DECLARE @ItemId int; set @ItemId =0;  Declare @IsExist as bit;  set @IsExist = 0;  select @IsExist = ItemId from Item where Item = @Item  if @IsExist = 0 begin Declare @ItemType nvarchar(50); select @ItemType = ItemType from Butchery where id = @Type  Insert into Item ( SBId, Item, GRId, ItemCode, [Type], Yield ) values ( @SBId, @Item, @GRId, @ItemCode, @ItemType, @Yield ) SET @ItemId = SCOPE_IDENTITY(); Commit if @ItemId > 0 begin  insert into ItemUnit ( ItemId, PkUnit, PkFactor, PurUnit, PurFactor, IssUnit, IssFactor, RecpUnit, RecpFactor   ) values ( @ItemId, @PkUnit, @PkFactor, @PurUnit, @PurFactor, @IssUnit,@IssFactor,@RecpUnit,@RecpFactor )Insert into ItemParLevel(ItemId,BRId,Parlevel,SId,DId)SELECT               @ItemId,		 myXML.value('./@BRId', 'int'), myXML.value('./@ParLevel', 'decimal (18,2)'),		 myXML.value('./@SId', 'int'),myXML.value('./@DId', 'int')    FROM @XML.nodes('/doc/title') As nodes(myXML);SET NOCOUNT OFF; END end END TRY BEGIN CATCH  IF @@TRANCOUNT > 0    ROLLBACK EXECUTE [uspGetErrorInfo] END CATCH select @ItemId;